import { animate, keyframes, state, style, transition, trigger } from '@angular/animations';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import {
  QChipChangeEvent,
  QChipComponent,
  QChipTextStyle,
  QChipVariant,
} from '@questrade/allspark-angular-components/chip';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { chevronDown, chevronUp } from '@questrade/allspark-icons/icons';
import { QSpoilerChangeEvent } from './types/spoiler-change-event.type';

@Component({
  selector: 'q-spoiler',
  imports: [QChipComponent],
  templateUrl: './spoiler.component.html',
  styleUrls: ['./spoiler.component.scss'],
  animations: [
    trigger('expansionFade', [
      state('collapsed', style({ opacity: 0 })),
      state('expanded', style({ opacity: 1 })),
      transition('collapsed <=> expanded', [animate('300ms ease-in-out')]),
    ]),
    trigger('textTransition', [
      state('showText', style({ opacity: 1 })),
      transition('showText <=> hideText', [
        animate(
          '300ms ease-in-out',
          keyframes([style({ opacity: 0, offset: 0 }), style({ opacity: 1, offset: 1 })]),
        ),
      ]),
    ]),
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QSpoilerComponent {
  @Output() readonly changed = new EventEmitter<QSpoilerChangeEvent>();

  @Input() chipTextStyle: QChipTextStyle = 'primary';
  @Input() chipType: QChipVariant = 'regular';
  @Input({ transform: booleanAttribute }) showChipIcon = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-spoiler';
  @Input() showText = 'Show';
  @Input() hideText = 'Hide';

  @HostBinding('class') _hostClass = 'q-spoiler';

  _opened = false;

  private readonly _iconRegistry = inject(QIconRegistryService);

  constructor() {
    this._iconRegistry.registerIcons([chevronUp, chevronDown]);
  }

  _onChipChanged(event: QChipChangeEvent<boolean>): void {
    this._opened = event.active;
    this.changed.emit({ opened: event.active });
  }

  get chipIcon(): string {
    return this.showChipIcon ? (this._opened ? 'chevronUp' : 'chevronDown') : '';
  }

  get chipText(): string {
    return this._opened ? this.hideText : this.showText;
  }
}
